"""Independent exhaustive reference planner: per-subset incremental usage vectors.

DP enumerates subsets of NON-pinned flows only; pinned flows are pre-applied
to node usage and added to the objective constants.
"""

def benefits_of(req):
    warmup = req['warmup']
    ben = {}
    for f in req['flows']:
        H = len(f['template']) // 2
        kinds = f['kinds']
        N = len(f['path']); h = N - 1
        per = (H - 4 - kinds.count('D')) * N
        t_off = kinds.index('T'); q_off = kinds.index('Q')
        k_off = [i for i, c in enumerate(kinds) if c == 'K']
        tmpl = bytes.fromhex(f['template'])
        left = warmup
        elig = 0
        for run in req['offers'][f['id']]:
            hdr = bytes.fromhex(run['header'])
            c = run['count']
            take = min(c, left)
            left -= take
            rest = c - take
            if rest and all(hdr[i] == tmpl[i] for i in k_off) and hdr[q_off] <= 7 and hdr[t_off] > h:
                elig += rest
        ben[f['id']] = per * elig
    return ben

def brute(req):
    """Returns (best_benefit, best_count) over full selected sets, or 'infeasible'."""
    cap = req['capacities']
    nodes = sorted(cap)
    nidx = {nd: i for i, nd in enumerate(nodes)}
    pinned = set(req['pinned'])
    flows = req['flows']
    fmap = {f['id']: f for f in flows}
    ben = benefits_of(req)
    puse = [0]*len(nodes)
    for fid in pinned:
        for nd in fmap[fid]['path']:
            puse[nidx[nd]] += 1
    for j, nd in enumerate(nodes):
        if puse[j] > cap[nd]:
            return 'infeasible'
    ids = [f['id'] for f in flows if f['id'] not in pinned]
    n = len(ids)
    fnodes = [frozenset(nidx[nd] for nd in fmap[fid]['path']) for fid in ids]
    limit = [cap[nd] - puse[j] for j, nd in enumerate(nodes)]
    zero = (0,)*len(nodes)
    # subset DP over non-pinned flows
    usage = {0: zero}
    bsum = {0: 0}
    csum = {0: 0}
    best_b = sum(ben[fid] for fid in pinned)
    best_c = len(pinned)
    for mask in range(1, 1 << n):
        lb = mask & -mask
        i = lb.bit_length() - 1
        prev = mask ^ lb
        if prev not in usage:
            continue
        u = usage[prev]
        ok = True
        for j in fnodes[i]:
            if u[j] + 1 > limit[j]:
                ok = False
                break
        if not ok:
            continue
        ul = list(u)
        for j in fnodes[i]:
            ul[j] += 1
        usage[mask] = tuple(ul)
        bsum[mask] = bsum[prev] + ben[ids[i]]
        csum[mask] = csum[prev] + 1
    for mask, b in bsum.items():
        bb = b + best_b
        cc = csum[mask] + best_c
        if bb > best_b or (bb == best_b and cc < best_c):
            best_b, best_c = bb, cc
    return (best_b, best_c)

def verify(req, got):
    """Returns (ok, why)."""
    ref = brute(req)
    if ref == 'infeasible':
        return (got == {'infeasible': True}), 'infeasible-mismatch'
    if 'infeasible' in got:
        return False, 'got-infeasible'
    sel = got['selected']
    fmap = {f['id']: f for f in req['flows']}
    if sel != sorted(set(sel)):
        return False, 'not-sorted-distinct'
    if not set(req['pinned']) <= set(sel):
        return False, 'pinned-missing'
    u = {}
    for fid in sel:
        if fid not in fmap:
            return False, 'unknown-flow'
        for nd in fmap[fid]['path']:
            u[nd] = u.get(nd, 0) + 1
            if u[nd] > req['capacities'][nd]:
                return False, 'cap-violated'
    ben = benefits_of(req)
    total = sum(ben[fid] for fid in sel)
    if got['saved'] != total:
        return False, f'saved-mismatch got={got["saved"]} exp={total} opt={ref[0]}'
    if total != ref[0]:
        return False, f'benefit-not-optimal got={total} opt={ref[0]}'
    if len(sel) != ref[1]:
        return False, f'count-not-min got={len(sel)} min={ref[1]}'
    return True, 'ok'
PYEOF
